CREATE TABLE IF NOT EXISTS "site_legal_documents" (
  "slug" text PRIMARY KEY,
  "title" text NOT NULL,
  "last_updated" text NOT NULL,
  "intro" text NOT NULL,
  "sections" jsonb NOT NULL,
  "updated_by_user_id" uuid REFERENCES "users"("id") ON DELETE SET NULL,
  "updated_at" timestamptz NOT NULL DEFAULT now()
);
--> statement-breakpoint
INSERT INTO "site_legal_documents" ("slug", "title", "last_updated", "intro", "sections")
VALUES (
  $slug$privacy$slug$,
  $title$Privacy Policy$title$,
  $upd$September 2026$upd$,
  $intro$This policy describes how we collect, use, and protect personal data in connection with nusman.dev, the Start a project and Contact flows, and the client Portal. It is designed to align with the EU GDPR (where it applies) and Ghana’s Data Protection Act, 2012 (Act 843).$intro$,
  $sec$[{"id":"controller","title":"1. Data controller and contact","paragraphs":["Data controller: Nuestman Tech Solutions (trading as the Numan Usman / nusman.dev practice). We are registered with the Office of the Registrar of Companies (ORC), Ghana, as Nuestman Links Enterprise, and the same entity is registered with the Data Protection Commission (DPC) for data protection compliance.","Address: AN758, Ivory Street, MVSS 27, Moinsi Valley Estate. For privacy requests, complaints, or questions (including data subject rights and Data Protection Commission matters), please use the contact details on this page.","Under Ghana's Data Protection Act, 2012 (Act 843), we are registered with the Data Protection Commission and ensure that our processing of personal data complies with the Act."]},{"id":"scope","title":"2. What this policy covers","paragraphs":["This policy covers personal data processed through the public website (nusman.dev), the Start a project and Contact flows, email and related communications, and the client Portal (portal.nusman.dev) when you are invited to use it.","The operator Desk (desk.nusman.dev) is a private workbench used to deliver projects. Data you share with us for a project may be stored there so we can manage the engagement. Desk is not a public product you sign up for.","If a separate written agreement (for example a proposal, statement of work, or data processing terms) says otherwise for a specific project, that agreement controls for that engagement."]},{"id":"data-we-collect","title":"3. Personal data we collect and why","paragraphs":["Contact and enquiry data: name, email, phone, organisation, and the messages or project brief you send (including Start a project answers such as problem, what you want built, timeline, and budget). Legal basis (GDPR where it applies): contract and/or legitimate interest. Under Ghana Act 843, processing follows the data protection principles.","Client Portal data: when Portal access is enabled for you, we process account identifiers (name, email), project updates, messages, schedule responses, and related files you or we share in the Portal. Legal basis: contract and legitimate interest in delivering the project.","Technical and usage data: logs, IP address, device/browser data, and similar information needed for security, availability, and abuse prevention. Legal basis: legitimate interest. We do not sell your personal data.","Project delivery data: material you provide so we can design, build, or support a system (which may include operational or health-related information if your project requires it). We process that only as needed for the engagement and under any written terms we agree."]},{"id":"how-we-use","title":"4. How we use personal data","paragraphs":["We use the data to respond to enquiries; evaluate and deliver projects; operate and secure the website, Portal, and Desk; send service messages (for example email confirmation, receipts, Portal magic links, and project updates); comply with law; and improve how we work, in line with applicable law."]},{"id":"legal-basis","title":"5. Legal basis for processing (GDPR)","paragraphs":["Where GDPR applies: Contract (delivering services you request); Legal obligation; Legitimate interest (security, support, improving the practice); Consent (where we rely on it, you may withdraw it at any time)."]},{"id":"retention","title":"6. Data retention","paragraphs":["We retain personal data only as long as needed for the purposes in this policy. Enquiry and lead data: for the sales/enquiry cycle and a reasonable period afterwards. Project and Portal records: for the life of the engagement and a reasonable archive period (or longer if law or a written agreement requires). Logs and security data: as needed for security and compliance. We then delete or anonymise data except where we must keep it for legal reasons."]},{"id":"rights","title":"7. Your rights","paragraphs":["GDPR (EEA/UK): You may have rights of access, rectification, erasure, restriction, portability, and objection; you may withdraw consent and lodge a complaint with a supervisory authority.","Ghana's Data Protection Act 843: Data subjects have rights including access, correction, and deletion in accordance with the Act. We will respond in line with the Act and the Data Protection Commission's guidelines.","To exercise these rights, contact us using the details in section 1."]},{"id":"security","title":"8. Security and confidentiality","paragraphs":["We implement technical and organisational measures appropriate to the risk, including access control, encryption in transit (TLS) where the Service is served over HTTPS, and careful handling of client and Portal credentials. Measures are aligned with GDPR Article 32 where it applies and Ghana Act 843."]},{"id":"cookies","title":"9. Cookies and similar technologies","paragraphs":["The public website (nusman.dev) does not set first-party cookies, does not use advertising or analytics cookies, and does not store authentication data in the browser’s local storage.","Desk (desk.nusman.dev) and the client Portal (portal.nusman.dev) use session cookies only — not advertising or tracking cookies. These are httpOnly, SameSite=lax, and Secure in production, and typically last about 14 days: desk_session (signed-in operator), desk_login_pending (short-lived step while finishing login or authenticator), and portal_session (signed-in client person). Switching between Desk and Portal clears the other surface’s session cookie.","We do not use third-party tracking cookies on these practice apps today. You can clear cookies in your browser; doing so will sign you out of Desk or Portal until you sign in again."]},{"id":"breaches","title":"10. Data breaches","paragraphs":["Where a breach is likely to result in a risk to rights and freedoms, we will notify the relevant authority and affected people as required by applicable law (including Ghana Act 843 reporting to the Data Protection Commission where required, and GDPR supervisory authority notice where it applies)."]},{"id":"transfers","title":"11. International transfers","paragraphs":["Personal data may be processed or stored in countries outside your country of residence (for example hosting or email providers). Where we transfer data from the EEA or UK, we use appropriate safeguards where required (for example standard contractual clauses). Where we transfer data from Ghana, we comply with cross-border requirements under Act 843. More detail is available on request."]},{"id":"dpo-ghana","title":"12. Data protection oversight (Ghana Act 843)","paragraphs":["In line with Ghana Act 843, we maintain internal oversight for data protection compliance. For enquiries about Act 843 compliance or to exercise rights under the Act, contact us at the details in section 1."]},{"id":"changes","title":"13. Changes to this policy","paragraphs":["We may update this Privacy Policy from time to time. The current version will be posted on nusman.dev with a “Last updated” date. Material changes may also be communicated by email or through the Portal when relevant. Please review this policy periodically."]},{"id":"contact","title":"14. Contact","paragraphs":["Nuestman Tech Solutions, AN758, Ivory Street, MVSS 27, Moinsi Valley Estate. For privacy, data subject rights, or Data Protection Commission–related enquiries, use the contact details on this page or email nuestman@icloud.com."]}]$sec$::jsonb
)
ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "site_legal_documents" ("slug", "title", "last_updated", "intro", "sections")
VALUES (
  $slug$terms$slug$,
  $title$Terms of Service$title$,
  $upd$September 2026$upd$,
  $intro$These Terms govern your use of nusman.dev and the client Portal, and sit alongside any written project agreement.$intro$,
  $sec$[{"id":"who","title":"1. Who these Terms apply to","paragraphs":["These Terms apply to visitors of nusman.dev and to clients (and their authorised users) who use the client Portal or engage Numan Usman / Nuestman Tech Solutions for project work.","If you use the Portal or request work on behalf of an organisation, you confirm you have authority to bind that organisation to these Terms for that use."]},{"id":"regulatory","title":"2. Regulatory context","paragraphs":["Our use of personal data is described in our Privacy Policy, which is designed to align with the EU GDPR (where it applies) and Ghana’s Data Protection Act, 2012 (Act 843).","As Nuestman Links Enterprise, we are registered with Ghana’s Data Protection Commission and maintain internal governance for Act 843 compliance."]},{"id":"site-portal","title":"3. Website and Portal","paragraphs":["The public site (nusman.dev) provides information about the practice and ways to start a conversation or project. You agree to use it lawfully and not to attempt unauthorised access or abuse of forms, APIs, or hosting.","The client Portal (portal.nusman.dev) is available only to people we invite for an active or ongoing engagement. Portal access may use magic-link email authentication. You must keep access to your email secure and not share Portal links intended only for you.","The Desk is an internal tool for delivering work. It is not offered as a self-serve public product under these Terms."]},{"id":"projects","title":"4. Project work","paragraphs":["Paid design, build, and related services are governed by the proposal, statement of work, invoice, or other written agreement we share with you. Those documents take priority over these Terms if they conflict on fees, scope, timelines, or deliverables.","You are responsible for the accuracy of information you provide, for decisions about your business or clinical operations, and for your own compliance with laws that apply to you. Software and advice we deliver support your work; they do not replace your policies, training, or professional judgement."]},{"id":"use","title":"5. Acceptable use","paragraphs":["You agree not to misuse the site or Portal — including attempting to break security, scrape in a way that harms the service, upload unlawful content, or use Portal messaging for emergencies that need immediate medical or safety response."]},{"id":"ip","title":"6. Intellectual property","paragraphs":["Unless a written project agreement says otherwise: (a) the nusman.dev site, branding, and practice materials remain ours; (b) deliverables we create for you under a paid engagement are licensed or assigned as set out in that engagement; (c) you keep ownership of materials you supply to us."]},{"id":"fees","title":"7. Fees and payment","paragraphs":["Fees, deposits, and payment terms for project work are as set out in your proposal, invoice, or written agreement. Late payment may pause work until payment is received. Fees are generally non-refundable except where required by law or expressly stated in writing."]},{"id":"confidentiality","title":"8. Confidentiality","paragraphs":["Each party will treat the other’s confidential information with reasonable care and use it only to provide or receive the services, or as otherwise agreed in writing or required by law."]},{"id":"warranty","title":"9. Warranties and disclaimers","paragraphs":["We provide services with reasonable skill and care. To the maximum extent permitted by law, the website and Portal are provided “as is” and “as available,” and we do not guarantee uninterrupted or error-free operation.","We do not warrant that use of the site, Portal, or deliverables alone will ensure your compliance with any particular law or regulation."]},{"id":"liability","title":"10. Limitation of liability","paragraphs":["To the maximum extent permitted by law, neither party is liable for indirect, consequential, or special damages (including loss of profits, revenue, or data) arising from the site, Portal, or these Terms.","Our aggregate liability for claims relating to the site, Portal, or these Terms is limited to the amounts you paid us for the relevant services in the 12 months before the claim, unless a different cap is set in a signed project agreement or required by law."]},{"id":"termination","title":"11. Suspension and termination","paragraphs":["We may suspend Portal or site access if use poses a security risk, involves abuse, or materially breaches these Terms and is not remedied after notice. Project termination follows your written agreement.","After access ends, we handle remaining data as described in the Privacy Policy and any data return or deletion terms we agreed."]},{"id":"changes","title":"12. Changes","paragraphs":["We may update the site, Portal, and these Terms from time to time. Material changes will be indicated by the “Last updated” date and, where appropriate, notice by email or Portal. Continued use after changes take effect means you accept the updated Terms, except where a signed project agreement requires a different process."]},{"id":"law","title":"13. Governing law","paragraphs":["Unless a signed commercial agreement says otherwise, these Terms and disputes relating to them or to the site/Portal are governed by the laws of Ghana, and the courts of Ghana have jurisdiction, without prejudice to mandatory rights under other applicable laws."]},{"id":"contact","title":"14. Contact","paragraphs":["For questions about these Terms, contact Nuestman Tech Solutions (registered as Nuestman Links Enterprise with Ghana ORC and DPC) at AN758, Ivory Street, MVSS 27, Moinsi Valley Estate, email nuestman@icloud.com, or phone +233 20 648 4034."]}]$sec$::jsonb
)
ON CONFLICT ("slug") DO NOTHING;
